<?php else:?><div class="app"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">H</span><span>HUIT <small>Schedule Hub</small></span></a><div class="sidebar-caption"><?=$admin ? 'Phòng đào tạo' : 'Giảng viên'?></div><nav><a class="active" href="index.php">▦ <span>Thời khóa biểu</span></a><?php if ($admin):?><a href="manage.php">▤ <span>Danh mục</span></a><a href="#schedule-form">＋ <span>Phân lịch mới</span></a><?php endif?><a href="#password">⚙ <span>Đổi mật khẩu</span></a></nav><div class="sidebar-bottom">Lịch giảng dạy<br><strong>Đa cơ sở, một nơi quản lý.</strong></div></aside><main class="workspace"><header class="topbar"><span>Thời khóa biểu / <?=$admin ? 'Tổng quan' : 'Cá nhân'?></span><div class="account"><span class="avatar"><?=h(mb_substr($user['name'], 0, 1))?></span><span><?=h($user['name'])?><small><?=$admin ? 'Phòng đào tạo' : 'Giảng viên'?></small></span><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><button class="link" name="action" value="logout">Đăng xuất</button></form></div></header><div class="content"><div class="page-heading"><div><p class="kicker"><?=$admin ? 'Quản lý giảng dạy' : 'Không gian giảng viên'?></p><h1><?=$admin ? 'Thời khóa biểu' : 'Lịch giảng dạy của tôi'?></h1><p><?=$admin ? 'Theo dõi và sắp xếp lịch giảng dạy tại các cơ sở.' : 'Xem lịch dạy, phòng học và cơ sở của bạn.'?></p></div><?php if ($admin):?><a href="#schedule-form" class="primary button">＋ &nbsp; Phân lịch mới</a><?php endif?></div><?php if ($error):?><div class="alert"><?=h($error)?></div><?php endif?><?php if (!empty($_SESSION['notice'])):?><div class="success"><?=h($_SESSION['notice'])?></div><?php unset($_SESSION['notice']);endif?>
<div class="summary-strip"><div><span>Khoảng thời gian</span><strong><?=h($begin->format('d/m'))?> – <?=h($finish->format('d/m/Y'))?></strong></div><div><span>Lịch phù hợp</span><strong><?=count($schedules)?> lịch</strong></div><div><span>Cơ sở</span><strong><?=count($branches)?> cơ sở</strong></div><?php if ($admin):?><div><span>Giảng viên</span><strong><?=count($teachers)?> người</strong></div><?php endif?></div><section class="panel calendar-panel"><div class="panel-heading"><div><h2>Thời khóa biểu</h2><p><?=$view === 'week' ? 'Xem các buổi dạy trong tuần' : 'Các lịch có buổi dạy trong tháng'?></p></div><div class="calendar-controls"><a class="icon-button" aria-label="Kỳ trước" href="<?=h(dateLink($d->modify($view === 'week' ? '-7 days' : 'first day of previous month')))?>">‹</a><a class="today-button" href="<?=h(dateLink(new DateTimeImmutable('today')))?>">Hôm nay</a><a class="icon-button" aria-label="Kỳ tiếp theo" href="<?=h(dateLink($d->modify($view === 'week' ? '+7 days' : 'first day of next month')))?>">›</a></div></div><form class="filters" method="get"><label>Chế độ<select name="view"><option value="week" <?=sel($view, 'week')?>>Theo tuần</option><option value="month" <?=sel($view, 'month')?>>Theo tháng</option></select></label><label>Ngày<input type="date" name="date" value="<?=h($d->format('Y-m-d'))?>"></label><?php if ($admin):?><label>Cơ sở<select name="branch"><option value="">Tất cả cơ sở</option><?php foreach ($branches as $b):?><option value="<?=$b['id']?>" <?=sel($_GET['branch'] ?? '', $b['id'])?>><?=h($b['branch_name'])?></option><?php endforeach?></select></label><label>Giảng viên<select name="teacher"><option value="">Tất cả giảng viên</option><?php foreach ($teachers as $t):?><option value="<?=$t['id']?>" <?=sel($_GET['teacher'] ?? '', $t['id'])?>><?=h($t['full_name'])?></option><?php endforeach?></select></label><?php endif?><label>Học kỳ<select name="term"><option value="">Tất cả học kỳ</option><?php foreach ($terms as $t):?><option value="<?=$t['id']?>" <?=sel($_GET['term'] ?? '', $t['id'])?>><?=h($t['name'])?></option><?php endforeach?></select></label><button class="secondary">Áp dụng</button></form>
<?php if ($view === 'week'):?><div class="week-grid"><div class="week-corner">Tiết</div><?php for ($i = 0;$i < 7;$i++):$dd = $week->modify("+$i days");?><div class="day-head <?=$dd->format('Y-m-d') === date('Y-m-d') ? 'is-today' : ''?>"><span><?=h($days[$i + 2])?></span><strong><?=$dd->format('d/m')?></strong></div><?php endfor?><?php for ($p = 1;$p <= 15;$p++):?><div class="period-label"><?=$p?></div><?php for ($i = 0;$i < 7;$i++):$dd = $week->modify("+$i days")->format('Y-m-d');?><div class="day-cell"><?php foreach ($schedules as $s):if ((int)$s['day_of_week'] !== $i + 2 || (int)$s['start_period'] !== $p || $dd < $s['start_date'] || $dd > $s['end_date']) {
    continue;
}$ex = $exceptionMap[$s['id'].'/'.$dd] ?? null;?><div class="event <?=$ex ? 'cancelled' : ''?>"><strong><?=h($s['subject_name'])?></strong><span>Tiết <?=$s['start_period']?>–<?=$s['end_period']?> · <?=h($s['room'])?></span><span><?=h($s['branch_name'])?></span><?php if ($admin):?><span><?=h($s['full_name'])?></span><a href="?edit=<?=$s['id']?>#schedule-form">Sửa lịch</a><?php endif?><?php if ($ex):?><span>Nghỉ: <?=h($ex['note'])?></span><?php if ($admin):?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="exception_id" value="<?=$ex['id']?>"><button class="link" name="action" value="restore">Khôi phục</button></form><?php endif?><?php endif?></div><?php endforeach?></div><?php endfor?><?php endfor?></div><p class="calendar-note">Mỗi thẻ được đặt tại tiết bắt đầu; khoảng tiết đầy đủ hiển thị trong thẻ.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Thứ / tiết</th><th>Học phần</th><th>Giảng viên</th><th>Cơ sở / phòng</th><th>Thời gian áp dụng</th></tr></thead><tbody><?php foreach ($schedules as $s):?><tr><td><?=h($days[$s['day_of_week']])?><br>Tiết <?=$s['start_period']?>–<?=$s['end_period']?></td><td><strong><?=h($s['subject_name'])?></strong><br><?=h($s['class_code'] ?? '')?></td><td><?=h($s['full_name'])?></td><td><?=h($s['branch_name'])?><br><?=h($s['room'])?></td><td><?=h($s['start_date'])?> — <?=h($s['end_date'])?></td></tr><?php endforeach?><?php if (!$schedules):?><tr><td colspan="5" class="empty">Không có lịch trong khoảng thời gian này.</td></tr><?php endif?></tbody></table></div><p class="calendar-note">Danh sách tháng hiển thị lịch định kỳ; ngày nghỉ được thể hiện trong chế độ tuần.</p><?php endif?></section>
<?php if ($admin):?><section class="panel" id="schedule-form"><div class="panel-heading"><div><h2><?=empty($edit['id']) ? 'Phân lịch giảng dạy' : 'Chỉnh sửa lịch giảng dạy'?></h2><p>Chọn học kỳ, học phần và thời gian để tìm giảng viên phù hợp.</p></div><?php if (!empty($edit['id'])):?><a href="index.php">Hủy chỉnh sửa</a><?php endif?></div><?php if (!$subjects || !$terms || !$rooms):?><div class="hint">Trước tiên, hãy thêm học phần, học kỳ và phòng học trong <a href="manage.php">Danh mục</a>.</div><?php endif?><form method="post" class="form-grid" id="schedule"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($edit['id'] ?? '')?>"><label>Học kỳ<select name="term_id" required><option value="">Chọn học kỳ</option><?php foreach ($terms as $t):?><option value="<?=$t['id']?>" <?=sel($edit['term_id'] ?? '', $t['id'])?>><?=h($t['name'])?></option><?php endforeach?></select></label><label>Học phần<select name="subject_id" required><option value="">Chọn học phần</option><?php foreach ($subjects as $s):?><option value="<?=$s['id']?>" <?=sel($edit['subject_id'] ?? '', $s['id'])?>><?=h($s['code'].' — '.$s['name'])?></option><?php endforeach?></select></label><label>Mã lớp học phần<input name="class_code" maxlength="80" required value="<?=h($edit['class_code'] ?? '')?>"></label><label>Cơ sở<select name="branch_id" required><option value="">Chọn cơ sở</option><?php foreach ($branches as $b):?><option value="<?=$b['id']?>" <?=sel($edit['branch_id'] ?? '', $b['id'])?>><?=h($b['branch_name'])?></option><?php endforeach?></select></label><label>Phòng học<select name="room_id" required><option value="">Chọn phòng</option><?php foreach ($rooms as $r):?><option data-branch="<?=$r['branch_id']?>" value="<?=$r['id']?>" <?=sel($edit['room_id'] ?? '', $r['id'])?>><?=h($r['branch_name'].' — '.$r['name'])?></option><?php endforeach?></select></label><label>Thứ<select name="day_of_week"><?php foreach ($days as $n => $name):?><option value="<?=$n?>" <?=sel($edit['day_of_week'] ?? 2, $n)?>><?=h($name)?></option><?php endforeach?></select></label><label>Tiết bắt đầu<input type="number" min="1" max="15" name="start_period" required value="<?=h($edit['start_period'] ?? 1)?>"></label><label>Tiết kết thúc<input type="number" min="1" max="15" name="end_period" required value="<?=h($edit['end_period'] ?? 3)?>"></label><label>Từ ngày<input type="date" name="start_date" required value="<?=h($edit['start_date'] ?? date('Y-m-d'))?>"></label><label>Đến ngày<input type="date" name="end_date" required value="<?=h($edit['end_date'] ?? date('Y-m-d'))?>"></label><label>Giảng viên<select name="teacher_id" required><option value="">Chọn giảng viên</option><?php foreach ($teachers as $t):?><option value="<?=$t['id']?>" <?=sel($edit['teacher_id'] ?? '', $t['id'])?>><?=h($t['full_name'])?></option><?php endforeach?></select></label><div class="suggestion" id="suggestions">Điền thông tin lịch để xem gợi ý.</div><div class="form-actions"><button class="primary">Lưu lịch giảng dạy</button><?php if (!empty($edit['id'])):?><button class="danger-button" name="action" value="delete" formnovalidate onclick="return confirm('Xóa lịch này?')">Xóa lịch</button><?php endif?></div></form><?php if (!empty($edit['id'])):?><details class="exception"><summary>Đánh dấu một buổi nghỉ</summary><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="exception"><input type="hidden" name="id" value="<?=h($edit['id'])?>"><label>Ngày nghỉ<input type="date" name="occurrence_date" required></label><label>Lý do<input name="note" maxlength="255" required></label><button class="secondary">Đánh dấu nghỉ</button></form></details><?php endif?></section><?php endif?><section class="panel compact-panel" id="password"><details><summary>Đổi mật khẩu</summary><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="password"><label>Mật khẩu hiện tại<input name="old_password" type="password" required></label><label>Mật khẩu mới<input name="new_password" type="password" minlength="8" required></label><button class="secondary">Đổi mật khẩu</button></form></details></section></div></main></div><script src="assets/js/app.js"></script><?php endif?></body></html>
